#include <paddle_inference_api.h>
#include <include/ocr_rec.h>
#include <opencv2/opencv.hpp>
#include <nlohmann/json.hpp>
#include <filesystem>
#include <fstream>
#include <numeric>
#include <algorithm>
#include <iostream>
using Json=nlohmann::json;
static Json Dump(paddle_infer::Tensor& tensor,const std::filesystem::path& path) {
    const auto shape=tensor.shape();
    const auto count=std::accumulate(shape.begin(),shape.end(),size_t(1),[](size_t a,int b){return a*b;});
    std::vector<float> data(count);tensor.CopyToCpu(data.data());
    std::ofstream stream(path,std::ios::binary);stream.write(reinterpret_cast<const char*>(data.data()),data.size()*sizeof(float));
    if(!stream)throw std::runtime_error("Cannot write actual tensor");
    const auto bounds=std::minmax_element(data.begin(),data.end());
    return {{"shape",shape},{"file",path.string()},{"floats",count},{"min",*bounds.first},{"max",*bounds.second}};
}
int wmain(int argc,wchar_t** argv) {
    try {
        if(argc!=4)throw std::runtime_error("Usage: probe model manifest output-directory");
        const std::filesystem::path model(argv[1]),manifest(argv[2]),out(argv[3]);
        if(std::filesystem::exists(out/"report.json"))throw std::runtime_error("Preserve old report");
        std::filesystem::create_directories(out);
        std::ifstream input(manifest);const auto cases=Json::parse(input).at("inputs");
        auto config=YAML::LoadFile((model/"inference.yml").string());
        auto dict=config["PostProcess"]["character_dict"].as<std::vector<std::string>>();
        std::ifstream keys(model/"ppocr_keys.txt");std::vector<std::string> fileDict;std::string s;
        while(std::getline(keys,s)){if(!s.empty()&&s.back()=='\r')s.pop_back();fileDict.push_back(s);}
        if(dict!=fileDict)throw std::runtime_error("Dictionary mismatch");
        PaddleOCR::CRNNRecognizer recognizer(model.string(),false,0,4000,4,true,(model/"ppocr_keys.txt").string(),false,"fp32",1,48,320);
        Json rows=Json::array();
        for(const auto& item:cases) {
            const auto id=item.at("id").get<std::string>();
            auto image=cv::imread(item.at("image").get<std::string>(),cv::IMREAD_COLOR);
            if(image.empty())throw std::runtime_error("Cannot read input");
            std::vector<std::string> texts(1);std::vector<float> scores(1);std::vector<double> times{0,0,0};
            recognizer.Run({image},texts,scores,times);
            const auto inputNames=recognizer.predictor_->GetInputNames();const auto outputNames=recognizer.predictor_->GetOutputNames();
            if(inputNames.size()!=1||outputNames.size()!=1)throw std::runtime_error("Unexpected model input/output count");
            auto feed=recognizer.predictor_->GetInputHandle(inputNames[0]);
            auto result=recognizer.predictor_->GetOutputHandle(outputNames[0]);
            rows.push_back({{"id",id},{"image",item.at("image")},{"imageShape",{image.rows,image.cols,3}},
                {"inputName",inputNames[0]},{"outputName",outputNames[0]},
                {"input",Dump(*feed,out/(id+".input.f32"))},{"output",Dump(*result,out/(id+".output.f32"))},
                {"text",texts[0]},{"score",scores[0]}});
        }
        Json report={{"scope","Actual post-Run input/output tensors from unchanged compiled CRNNRecognizer; diagnostic-only header access."},
            {"model",model.string()},{"characterClasses",recognizer.label_list_},{"mkldnn",true},{"threads",4},{"cases",rows}};
        std::ofstream stream(out/"report.json");stream<<report.dump(2)<<'\n';
        std::cout<<"Captured actual tensors for "<<rows.size()<<" cases\n";return 0;
    }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}
}
